var ML = window.__ML || (window.__ML = {});

ML.pill = function(i, value, unit, tone){
  MSD.q('#ml-pill-v-' + i).textContent = value;
  if(unit !== null) MSD.qa('#ml-pill-' + i + ' .ml-pill-u')[0].textContent = unit;
  MSD.cls('#ml-pill-' + i, 'bad', tone === 'bad');
  MSD.cls('#ml-pill-' + i, 'good', tone === 'good');
};

// Which nodes exist, and which one this stage is about.
ML.nodes = function(list, live){
  ['app','fd','api','db','entra'].forEach(function(n){
    MSD.cls('#ml-n-' + n, 'on', list.indexOf(n) !== -1);
    MSD.cls('#ml-n-' + n, 'live', (live || []).indexOf(n) !== -1);
  });
};

// Wires: on = drawn, flow = dots moving, dead = drawn but faded.
ML.wires = function(map){
  ['direct','a1','a2','a3','entra'].forEach(function(id){
    var v = map[id] || ['off', ''];
    var el = '#ml-w-' + id;
    MSD.cls(el, 'on',   v[0] !== 'off');
    MSD.cls(el, 'flow', v[0] === 'flow');
    MSD.cls(el, 'dead', v[0] === 'dead');
    MSD.cls(el, 'hot',  v[1] === 'hot');
    MSD.cls(el, 'bad',  v[1] === 'bad');
  });
};

ML.cnt = function(node, value){
  var el = '#ml-c-' + node;
  MSD.cls(el, 'on', value !== null);
  if(value !== null) MSD.q(el).textContent = value;
};

// The code block. lines is an array of HTML strings; active is 1-based.
ML.code = function(file, lines, active, gone, tone){
  MSD.q('#ml-code-h').textContent = file;
  for(var i = 1; i <= 5; i++){
    MSD.q('#ml-ln-' + i).innerHTML = lines[i - 1] || '';
    MSD.cls('#ml-ln-' + i, 'active', i === active);
    MSD.cls('#ml-ln-' + i, 'gone', (gone || []).indexOf(i) !== -1);
  }
  MSD.cls('#ml-code', 'bad', tone === 'bad');
  MSD.cls('#ml-code', 'good', tone === 'good');
};

ML.OPEN = [
  '<span class="c">// anyone who knows the URL can call this</span>',
  'app.<span class="f">MapGet</span>(<span class="s">"/orders"</span>, () =&gt;',
  '    db.Orders.<span class="f">ToList</span>());',
  '',
  '<span class="c">// no token. no owner check. public database.</span>'
];

ML.SAFE = [
  'builder.Services.<span class="f">AddAuthentication</span>()',
  '    .<span class="f">AddMicrosoftIdentityWebApi</span>(config);',
  'app.<span class="f">MapGet</span>(<span class="s">"/orders"</span>, (ClaimsPrincipal me) =&gt;',
  '    db.Orders.<span class="f">Where</span>(o =&gt; o.UserId == me.Oid))',
  '   .<span class="f">RequireAuthorization</span>();'
];

/* ------------------------------------------- opening state -------- */
MSD.cls('#ml-map', 'dim', false);
MSD.cls('#ml-payoff', 'on', false);
MSD.cls('#ml-cut', 'on', false);

ML.pill(1, '2', 'doors', '');
ML.pill(2, '0', '', '');
ML.nodes(['app', 'db'], []);
ML.wires({ direct: ['on', ''] });
ML.cnt('app', null); ML.cnt('fd', null); ML.cnt('api', null); ML.cnt('entra', null);
ML.cnt('db', '1');
ML.code('Program.cs · your API', ML.OPEN, 2, [], '');

MSD.after(400, function(){
  ML.wires({ direct: ['flow', ''] });
  ML.nodes(['app', 'db'], ['app']);
  MSD.sfx.whoosh();
});
MSD.after(1300, function(){ MSD.punch('#ml-n-db', 3); MSD.sfx.blip(3); });
MSD.after(2100, function(){ MSD.punch('#ml-c-db', 4); });

var ML = window.__ML;

ML.pill(1, '2', 'doors', 'bad');
ML.pill(2, '0', '', 'bad');
ML.nodes(['app', 'db'], []);
ML.wires({ direct: ['flow', 'bad'] });
ML.cnt('db', '1');
ML.code('Program.cs · your API', ML.OPEN, 2, [], 'bad');

MSD.after(300,  function(){ MSD.punch('#ml-ln-5', 2); MSD.sfx.error(); });
MSD.after(1100, function(){ MSD.shake('#ml-code'); });
MSD.after(1800, function(){
  ML.wires({ direct: ['dead', 'bad'] });
  MSD.cls('#ml-cut', 'on', true);
  MSD.sfx.thud();
});

var ML = window.__ML;

